          '**Ограниченный контроль над разметкой.** Иерархию заголовков, атрибуты и порядок блоков в коде определяет шаблон. Поправить можно только то, что предусмотрели разработчики платформы.',
          '**Микроразметка — вручную и частично.** Schema.org для услуг, товаров, хлебных крошек и вопросов-ответов в конструкторе приходится вставлять HTML-блоками на каждой странице, и поддерживать её в актуальном состоянии некому.',
          '**Каталог без SEO-логики.** Посадочные страницы под фильтры («диваны серые угловые»), канонические адреса, управление дублями — всё это требует серверной логики, которой у конструктора нет.',
