          '**Воронка продаж из коробки.** Этапы сделки, задачи, напоминания, история общения с клиентом — именно то, ради чего CRM обычно и покупают.',
          '**Телефония, почта и мессенджеры.** Звонки записываются в карточку, письма и сообщения собираются в одном окне.',
