          '**Данные живут в трёх местах и не сходятся.** Сделки в CRM, остатки в складской программе, график в Excel. Ответ на вопрос «сколько мы заработали на этом объекте» требует ручной сверки.',
          '**Сотрудники переносят данные руками.** Заявку из мессенджера копируют в карточку, оплату отмечают по выписке, статус из таблицы переписывают в CRM. Каждый такой перенос — время и ошибки.',
