    category: 'Поддержка',
    excerpt: 'Проект достался от другого разработчика, документации нет, а менять что-то нужно уже сейчас. Рассказываем, как устроен технический аудит: что смотрим по дням, как оцениваем риски и что вы получаете на выходе.',
    cover: '/assets/images/journal/audit-cover.png',
    ogImage: '/img/og/journal-audit.jpg',
    publishedAt: '2026-10-08',
