          '**«мёртвый» код и самописные решения.** Модули, которые никто не вызывает, и собственные велосипеды там, где есть проверенная библиотека;',
          '**процесс выкатки.** Как новая версия попадает на сервер: автоматически из репозитория или копированием файлов по FTP.',
