    excerpt: 'Подрядчики всё чаще предлагают «добавить llms.txt для нейросетей». Разбираем честно: что это за файл, кто его на самом деле читает, чем он отличается от robots.txt и sitemap.xml и стоит ли тратить на него время.',
    cover: '/assets/images/journal/llms-cover.png',
